import raw from '../data/airports.json';
import type { Airport } from '../models.ts';
import { distanceKm } from '../geo.ts';

type Row = [string, string, string, number, number, number, number, string, string];

// Generated by scripts/build-airports.mjs from OurAirports.
export const airports: Airport[] = (raw as Row[]).map(
  ([icao, iata, name, lat, lon, elevationFt, large, country, city]) => ({
    icao, iata, name, lat, lon, elevationFt, isLarge: large === 1, country, city,
  }),
);

export const airportLabel = (a: Airport) => a.iata || a.icao;

export function nearestAirport(lat: number, lon: number): { airport: Airport; distKm: number } | null {
  let best: Airport | null = null;
  let bestDist = Infinity;
  for (const a of airports) {
    // cheap pre-filter before the trig
    if (Math.abs(a.lat - lat) > 2 || Math.abs(a.lon - lon) > 4) continue;
    const d = distanceKm(lat, lon, a.lat, a.lon);
    if (d < bestDist) { best = a; bestDist = d; }
  }
  return best ? { airport: best, distKm: bestDist } : null;
}
